def minPath(grid, k):
n = len(grid)
# Find position of each value
pos = {}
for i in range(n):
    for j in range(n):
        pos[grid[i][j]] = (i, j)

# dp[step][i][j] = best path of length step starting from (i,j)
# But that's too big. Instead, for each step from k down to 1, track best path.
# Actually work backwards: for step s, we want best path of length s starting from each cell.

# best[i][j] = best path of length remaining starting from (i,j)
# Start with remaining=1: best[i][j] = [grid[i][j]]

best = [[None] * n for _ in range(n)]
for i in range(n):
    for j in range(n):
        best[i][j] = [grid[i][j]]

for remaining in range(2, k+1):
    new_best = [[None] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            candidates = []
            for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
                ni, nj = i+di, j+dj
                if 0 <= ni < n and 0 <= nj < n:
                    candidates.append([grid[i][j]] + best[ni][nj])
            # Find lexicographically smallest
            new_best[i][j] = min(candidates)
    best = new_best

# Find overall minimum
result = None
for i in range(n):
    for j in range(n):
        if result is None or best[i][j] < result:
            result = best[i][j]
return result

